def find_arithmetic_progressions(points, tolerance=0.1):
    """Find arithmetic progressions in a given direction"""
    prog = []

    # Check horizontal (same row)
    by_row = defaultdict(list)
    for r, c in points:
        by_row[r].append(c)

    for r, cols in by_row.items():
        cols_sorted = sorted(cols)
        for i in range(len(cols_sorted)):
            for j in range(i+1, len(cols_sorted)):
                a = cols_sorted[i]
                b = cols_sorted[j]
                d = b - a
                # Find all points forming AP
                sequence = [a]
                current = b
                while True:
                    next_val = current + d
                    if next_val in cols_sorted[current+cols_sorted.index(current):]:
                        sequence.append(next_val)
                        current = next_val
                    else:
                        break
                if len(sequence) >= 3:
                    prog.append({'row': r, 'cols': sequence, 'diff': d, 'count': len(sequence)})

    # Check vertical (same column)
    by_col = defaultdict(list)
    for r, c in points:
        by_col[c].append(r)

    for c, rows in by_col.items():
        rows_sorted = sorted(rows)
